CASES += [
    # numeric solving beyond -20..20; x^1.5 = k no longer crashes
    ('73573-jun19', '8bii', 'casui:CAS', 'solve exact f(x)=0', '5(4+11e^(-0.068066x))=21', 'x = 58.87', None, False, False),
    ('73573-nov20', '5a', 'casui:CAS', 'solve exact f(x)=0', 'e^(-0.0435935x)=0.1', 'x = 52.8', None, False, False),
    ('73573-jun22', '7b', 'casui:CAS', 'solve exact f(x)=0', '0.2*x^1.5=60000', 'x = 4481', None, False, False),
    ('73571-jun18', '11b', 'casui:CAS', 'solve exact f(x)=0', '10+100(x/30)^3-50(x/30)^4=4.5*1.063^x', 'x = 49.009', None, False, False),
    # letters as parameters in CAS solve and factorise
    ('73572-jun19', '7bi', 'casui:CAS', 'solve exact f(x)=0', '3x^2+6p*x=0', 'x = -2*p', None, False, False),
    ('73572-jun19', '7bi', 'casui:CAS', 'factorise', '3x^2+6p*x', '3*x*(x+2*p)', None, False, False),
    # the lost a^k of N/(ax+b)^k
    ('73572-jun24', '9ci', 'casui:CAS', 'series (Maclaurin)', '12x/((1+3x)(2-3x))', '-9*x^2+6*x', '3', False, False),
    ('73572-jun24', '9ci', 'casui:CAS', 'd/dx', '12x/((1+3x)(2-3x))', '(108*x^2+24)/((3*x+1)^2*(3*x-2)^2)', None, False, False),
    ('73573-jun22', '10d', 'mcalc:G', 'Stationary points', '(x^2+10)/(2x+5)', "f'(x) = (2*x^2+10*x-20)/(2*x+5)^2", None, False, False),
    # real cube root
    ('73571-jun19', '15ai', 'casui:Calculate', 'Calculate', '(-3)^(1/3)', '-1.44224957', None, False, False),
]

def run(check):
    for paper, q, module, label, inputs, expected, ask, deg, full in CASES:
        out = tests_pastpapers.output(module, label, inputs, ask, deg, full)
        check('past paper ' + paper + ' Q' + q + ' ' + label + ' <' + inputs + '>: has ' + repr(expected),
              expected in out, out.replace('\n', ' | ')[:300])

if __name__ == '__main__':
    import sys
    import casutil
    import plot
    plot.run = lambda *a, **k: None
    casutil.pick = lambda *a, **k: None
    fails = []
    n = [0]

    def chk(label, cond, detail=''):
        n[0] += 1
        if not cond:
            fails.append(label + '  [' + str(detail) + ']')
    run(chk)
    for f in fails:
        print('FAIL  ' + f)
    print(str(n[0]) + ' checks, ' + str(len(fails)) + ' failures')
    sys.exit(1 if fails else 0)
